head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergeCellsFixedCols]<br/>Body 의 고정 Column 영역에서 동일한 값이 연속되는 Cell 을 자동으로 병합하는 방식을 설정합니다.",
    "validation" : [
        "fixedColumn 으로 고정된 Column 영역에 적용됩니다.",
        "displayFormat 등의 포맷 속성이 적용되지 않은 원본 데이터와 초기 Column 위치를 기준으로 병합 처리됩니다.",
        "'never'(기본값) 설정 시 고정 Column 영역에서 동일 Cell 값에 대한 병합을 수행하지 않습니다.",
        "'bycol' 설정 시 같은 Column 내에서 동일한 값이 연속되는 Cell 에 rowSpan 방식의 세로 병합을 수행합니다.",
        "'byrow' 설정 시 같은 Row 내에서 동일한 값이 연속되는 Cell 에 colSpan 방식의 가로 병합을 수행합니다.",
        "동일한 이름의 mergeCellsFixedCols() 메소드를 사용하여 동적으로 속성을 설정할 수 있습니다.",
        "mergeCellsFixedCols 속성은 'bycolupper' 방식은 지원하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 고정 영역(col1~col3) 과 비고정 영역(col4) 의 병합 차이를 보여주도록 구성.
//  · col1(고정) : A,A,B,B          → 세로(bycol) 동일값 연속 : [0~1]=A / [2~3]=B
//  · col2(고정) : P,P,P,P          → 행0 에서 col2=col3=P 가로(byrow) 동일값 / 세로도 동일값
//  · col3(고정) : P,Q,Q,R (행0 만 col2 와 같은 P) → 행0 가로병합 검증용
//  · col4(비고정,displayFormat) : 1000,1000,1000,1000 (원본 동일) → 비고정이라 어떤 옵션에서도 미병합(validation #1)
//    또 displayFormat="#,##0" 으로 표시값은 1,000 이나 병합은 원본(1000) 기준(validation #2)
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "P", "col3": "P", "col4": "1000" },
    { "col1": "A", "col2": "P", "col3": "Q", "col4": "1000" },
    { "col1": "B", "col2": "P", "col3": "Q", "col4": "1000" },
    { "col1": "B", "col2": "P", "col3": "R", "col4": "1000" }
];



// comp 생성 : fixedColumn=3 (col1~col3 고정) 그리드 1개를 동적 생성한다.
//  ★ mergeCellsFixedCols 는 생성 attribute 로 주지 않고, 데이터 적재+렌더 후 mergeCellsFixedCols() 메소드로 적용한다.
//     (초기 렌더 중 세로병합하면 흡수 Row 가 height 0 으로 collapse 되는 현상 회피 + @spec 동일 이름 메소드 입증)
//  ★ con 미설정('') 이면 메소드를 호출하지 않음(기본 never).
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // con_ 설정값 수집 : '' 미설정(메소드 미호출=기본 never) / never / bycol / byrow
    let vMerge = con_mergeCellsFixedCols.getValue();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="mergeCellsFixedCols=' + (vMerge === '' ? '(미설정)' : vMerge) + ' / fixedColumn=3 (col1~col3 고정), col4=비고정+displayFormat. 고정 영역만 병합되고 col4(비고정,동일값 1000)는 미병합"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedColumn=3 으로 왼쪽 3개 컬럼 고정
    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id, fixedColumn: 3 });

    // target 생성 (mergeCellsFixedCols 속성은 부여하지 않음 → 아래에서 메소드로 적용)
    //  · col4 : 비고정 + displayFormat="#,##0" (원본 1000 vs 표시 1,000)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    //  ★ 컬럼 폭 합(420)을 그리드 폭(300)보다 크게 하여 가로 스크롤이 생기도록 함 → col1~col3(좌측 고정)이 스크롤해도 그대로 남는 것을 확인.
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:300px;height:235px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedCols sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column2" value="col2(고정)"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column3" value="col3(고정)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column4" value="col4(비고정,포맷)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" dataType="number" displayFormat="#,##0" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 생성(데이터 적재 완료) 후 mergeCellsFixedCols() 메소드로 병합 적용 (미설정 시 미호출=기본 never)
    if (vMerge !== '') {
        let grid = $p.getComponentById("target1");
        grid.mergeCellsFixedCols(vMerge);
    }
}



// 병합 상태 확인 : 고정 영역 td 의 rowSpan/colSpan 을 직관 출력(⬇세로/➡가로) + 비고정(col4) 미병합 확인
//  - 고정 영역 td 는 _fixedColumnDiv 안에 위치하며 id 는 target1_cell_{row}_{col} 형태(scroll 영역과 중복 id 가능)
//  - 화면에 표시되는(흡수되지 않은) td 만 대상으로 rowSpan/colSpan 을 읽어 판정
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let gid = target1.id;
    bottom.setReturnValue("[옵션] mergeCellsFixedCols : " + target1.options.mergeCellsFixedCols + " / fixedColumn : " + target1.options.fixedColumn);

    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let col4Merged = false;
    let descs = [];

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        // col4(비고정) = colIndex 3
        if (rs > 1 || cs > 1) {
            if (c === 3) col4Merged = true;
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let mode;
    if (rowSpanCnt === 0 && colSpanCnt === 0) mode = "never (병합 없음)";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) mode = "bycol (세로 병합)";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) mode = "byrow (가로 병합)";
    else mode = "혼합";

    bottom.setReturnValue("판정 : " + mode + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
    bottom.setReturnValue("비고정(col4) 영역 병합 여부 : " + col4Merged + " (false 면 비고정 영역 미병합 → 고정 영역에만 적용)");
}
